beforeExample:
package test;
import org.eclipse.swt.SWT;
public class Example {
    public void foo(int stateMask) {
        if (stateMask == SWT.CONTROL) {
            System.out.println("Ctrl pressed only");
        }
    }
}

afterExample:
package test;
import org.eclipse.swt.SWT;
public class Example {
    public void foo(int stateMask) {
        if ((stateMask & SWT.MODIFIER_MASK) == SWT.CONTROL) {
            System.out.println("Ctrl pressed only");
        }
    }
}

negativeExample:
package test;
import org.eclipse.swt.SWT;
public class Negative {
    public void bar(int stateMask) {
        if (stateMask == SWT.SHIFT) { // Different constant
            System.out.println("Shift pressed");
        }
        if (stateMask == 5) { // Literal value
            System.out.println("Literal int");
        }
    }
}
